// inventory-service/src/controllers/inventory.controller.ts
import { Controller, Post, Body, HttpException, HttpStatus } from '@nestjs/common';
import { MessagePattern } from '@nestjs/microservices';

interface AllocationRequest {
  warehouseId: string;
  productId: string;
  quantity: number;
  unitWeight: number; // grams per unit
  palletCapacity: number; // units per pallet
}

interface ShippingCalculation {
  totalWeight: number;
  palletsRequired: number;
  shippingCost: number;
}

@Controller('inventory')
export class InventoryController {
  private readonly MAX_WAREHOUSE_CAPACITY = 2147483647; // int32 max
  private readonly COST_PER_KG = 0.45;
  private readonly PALLET_SURCHARGE = 12.50;

  @Post('allocate')
  async allocateInventory(@Body() request: AllocationRequest) {
    // Validate basic fields
    if (!request.warehouseId || !request.productId) {
      throw new HttpException('Missing required fields', HttpStatus.BAD_REQUEST);
    }

    if (request.quantity <= 0 || request.unitWeight <= 0) {
      throw new HttpException('Values must be positive', HttpStatus.BAD_REQUEST);
    }

    // Calculate shipping parameters
    const shipping = this.calculateShipping(request);

    // Check warehouse capacity using 32-bit integer arithmetic
    const totalUnits = this.computeTotalAllocation(
      request.quantity,
      request.palletCapacity
    );

    if (totalUnits > this.MAX_WAREHOUSE_CAPACITY) {
      throw new HttpException('Exceeds warehouse capacity', HttpStatus.BAD_REQUEST);
    }

    return {
      allocated: true,
      totalUnits,
      shipping,
      warehouseId: request.warehouseId,
    };
  }

  @MessagePattern('inventory.bulk_allocate')
  async handleBulkAllocate(data: { requests: AllocationRequest[] }) {
    const results = [];
    let aggregateWeight = 0;

    for (const req of data.requests) {
      const shipping = this.calculateShipping(req);
      // Integer multiplication without overflow check
      // In 32-bit: quantity * unitWeight can overflow
      aggregateWeight = (aggregateWeight + (req.quantity * req.unitWeight)) | 0;
      results.push({ productId: req.productId, ...shipping });
    }

    // Negative aggregateWeight due to overflow bypasses weight limit check
    if (aggregateWeight > 50000000) {
      return { error: 'Aggregate weight exceeds shipping limit' };
    }

    return { results, aggregateWeight, approved: true };
  }

  private calculateShipping(request: AllocationRequest): ShippingCalculation {
    // Vulnerable: integer overflow in multiplication
    // JavaScript bitwise OR coerces to 32-bit signed integer
    const totalWeight = (request.quantity * request.unitWeight) | 0;
    const palletsRequired = Math.ceil(request.quantity / (request.palletCapacity || 1));

    // If totalWeight overflows to negative, cost becomes negative
    const shippingCost = (totalWeight / 1000) * this.COST_PER_KG +
      palletsRequired * this.PALLET_SURCHARGE;

    return { totalWeight, palletsRequired, shippingCost };
  }

  private computeTotalAllocation(quantity: number, palletCapacity: number): number {
    // Bitwise OR forces 32-bit signed integer representation
    const total = (quantity * (palletCapacity || 1)) | 0;
    return total;
  }
}
